insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Incumbe ao Conselho da Comunidade visitar, pelo menos mensalmente, os estabelecimentos penais da comarca; entrevistar presos; apresentar relatórios mensais ao Juiz da execução e ao Conselho Penitenciário; e diligenciar a obtenção de recursos materiais e humanos para melhor assistência ao preso ou internado, em harmonia com a direção do estabelecimento.', '["Visita mensal.","Entrevista de presos.","Relatórios mensais ao juiz e ao Conselho Penitenciário.","Busca de recursos."]'::jsonb, '["Visita e relatório MENSAIS."]'::jsonb, 'O Conselho da Comunidade entrega relatório mensal ao juiz da execução.', '["Assertiva que fixa visitas trimestrais ao Conselho da Comunidade erra: são, no mínimo, mensais."]'::jsonb, '[]'::jsonb, '["Art. 80"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-81'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A Defensoria Pública velará pela regular execução da pena e da medida de segurança, oficiando, no processo executivo e nos incidentes da execução, para a defesa dos necessitados em todos os graus e instâncias, de forma individual e coletiva.', '["Fiscaliza a execução.","Defesa dos necessitados, individual e coletiva."]'::jsonb, '["Atuação individual E coletiva."]'::jsonb, 'A Defensoria defende o preso hipossuficiente e também age em favor de grupos de presos.', '["Assertiva que limita a Defensoria à defesa individual erra: também atua coletivamente."]'::jsonb, '[]'::jsonb, '["Art. 81-B"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-81-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Incumbe ainda à Defensoria Pública requerer as providências necessárias ao processo executivo; a aplicação de lei posterior mais benéfica; a extinção da punibilidade; a unificação de penas; a detração e a remição; os incidentes de excesso ou desvio de execução; a medida de segurança e sua revogação; a conversão de penas, a progressão, a suspensão condicional, o livramento condicional, a comutação e o indulto; as saídas temporárias; a internação e a desinternação; o cumprimento em outra comarca; e outras medidas em favor do assistido.', '["Requerer progressão, livramento, remição e detração.","Indulto, comutação e saídas temporárias.","Incidentes de excesso ou desvio."]'::jsonb, '["Rol de requerimentos da Defensoria em favor do assistido."]'::jsonb, 'A Defensoria requer a progressão de regime do assistido.', '["Assertiva que impede a Defensoria de requerer indulto e comutação erra."]'::jsonb, '[]'::jsonb, '["Art. 81-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-81-b'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os estabelecimentos penais destinam-se ao condenado, ao submetido à medida de segurança, ao preso provisório e ao egresso. A mulher e o maior de sessenta anos, separadamente, serão recolhidos a estabelecimento próprio e adequado à sua condição pessoal. O mesmo conjunto arquitetônico poderá abrigar estabelecimentos de destinação diversa, desde que devidamente isolados.', '["Destinatários: condenado, internado, preso provisório e egresso.","Mulher e maior de 60 anos em estabelecimento próprio.","Estabelecimentos diversos no mesmo conjunto, se isolados."]'::jsonb, '["Mulher e maior de sessenta anos: estabelecimentos SEPARADOS e próprios."]'::jsonb, 'A mulher presa é recolhida em unidade feminina.', '["Assertiva que permite recolher a mulher e o idoso em qualquer estabelecimento comum erra."]'::jsonb, '[]'::jsonb, '["Art. 83"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-82'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O estabelecimento penal, conforme a sua natureza, deverá contar com áreas e serviços destinados a dar assistência, educação, trabalho, recreação e prática esportiva. Haverá instalação destinada a estágio de estudantes universitários. Os estabelecimentos femininos serão dotados de berçário, onde as condenadas possam cuidar de seus filhos e amamentá-los, no mínimo, até 6 meses de idade, e possuirão exclusivamente agentes do sexo feminino na segurança das dependências internas. Serão instaladas salas de aula e haverá instalação destinada à Defensoria Pública.', '["Áreas de assistência, educação, trabalho, recreação e esporte.","Instalação para estágio universitário.","Berçário até, no mínimo, 6 meses.","Agentes exclusivamente femininos.","Salas de aula e instalação da Defensoria."]'::jsonb, '["Berçário: no mínimo até 6 meses de idade."]'::jsonb, 'O presídio feminino tem berçário para a mãe amamentar.', '["Assertiva que dispensa o berçário nos presídios femininos erra."]'::jsonb, '[]'::jsonb, '["Art. 89"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-83'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Poderão ser objeto de execução indireta as atividades materiais acessórias, instrumentais ou complementares desenvolvidas em estabelecimentos penais, notadamente os serviços de conservação, limpeza, informática, copeiragem, portaria, recepção, reprografia, telecomunicações, lavanderia e manutenção, e os serviços relacionados à execução de trabalho pelo preso. A execução indireta ocorre sob supervisão e fiscalização do poder público e pode compreender o fornecimento de materiais, equipamentos, máquinas e profissionais.', '["Execução indireta de atividades acessórias.","Sob supervisão do poder público.","Fornecimento de materiais e profissionais."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído por lei posterior (terceirização penitenciária).","Só atividades ACESSÓRIAS podem ser terceirizadas."]'::jsonb, 'A limpeza do presídio é feita por empresa contratada.', '["Assertiva que permite terceirizar a direção do presídio erra: a direção é indelegável."]'::jsonb, '[]'::jsonb, '["Art. 83-B"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-83-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'São indelegáveis as funções de direção, chefia e coordenação no âmbito do sistema penal, bem como todas as atividades que exijam o exercício do poder de polícia, notadamente a classificação de condenados, a aplicação de sanções disciplinares, o controle de rebeliões e o transporte de presos para órgãos do Judiciário, hospitais e outros locais externos.', '["Direção, chefia e coordenação indelegáveis.","Poder de polícia indelegável.","Classificação, sanções, controle de rebeliões e transporte externo."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído por lei posterior.","Indelegável: poder de polícia."]'::jsonb, 'O transporte do preso ao fórum não pode ser terceirizado.', '["Assertiva que permite delegar o controle de rebeliões a empresa privada erra."]'::jsonb, '[]'::jsonb, '["Art. 83-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-83-b'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O preso provisório ficará separado do condenado por sentença transitada em julgado. Os provisórios são separados conforme os acusados de crimes hediondos ou equiparados; de crimes com violência ou grave ameaça; e de outros crimes ou contravenções. O preso que, ao tempo do fato, era funcionário da Administração da Justiça Criminal ficará em dependência separada. Os condenados são separados em condenados por crimes hediondos ou equiparados; reincidentes por crimes com violência ou grave ameaça; primários por esses crimes; e demais condenados. O preso com integridade ameaçada pela convivência ficará segregado em local próprio.', '["Separação do provisório e do condenado definitivo.","Critérios de separação dos provisórios e dos condenados.","Funcionário da Justiça Criminal em dependência separada.","Segregação do preso ameaçado."]'::jsonb, '["ATUALIZAÇÃO: critérios de separação ampliados por lei posterior.","Provisório SEPARADO do condenado."]'::jsonb, 'O ex-policial preso fica em dependência separada.', '["Assertiva que permite misturar presos provisórios e condenados erra."]'::jsonb, '[]'::jsonb, '["Art. 102"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-84'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O estabelecimento penal deverá ter lotação compatível com a sua estrutura e finalidade. O Conselho Nacional de Política Criminal e Penitenciária determinará o limite máximo de capacidade do estabelecimento, atendendo a sua natureza e peculiaridades.', '["Lotação compatível com a estrutura.","Limite máximo definido pelo Conselho Nacional."]'::jsonb, '["Quem fixa o limite de capacidade é o Conselho NACIONAL."]'::jsonb, 'O Conselho Nacional define a capacidade máxima de cada unidade.', '["Assertiva que atribui ao diretor a fixação da capacidade máxima erra."]'::jsonb, '[]'::jsonb, '["Art. 64"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-85'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As penas privativas de liberdade aplicadas pela Justiça de uma Unidade Federativa podem ser executadas em outra unidade, em estabelecimento local ou da União. A União poderá construir estabelecimento penal em local distante da condenação, quando a medida se justifique no interesse da segurança pública ou do próprio condenado. Caberá ao juiz competente, no prazo de 24 horas, a requerimento da administração penitenciária, definir o estabelecimento adequado. Será transferido para outra unidade federativa o condenado ou provisório que, tendo cometido violência doméstica contra a mulher, ameace ou pratique violência contra a vítima ou familiares. Em risco iminente e grave, a administração poderá transferir presos em caráter excepcional, comunicando ao juiz.', '["Execução em outra unidade federativa ou da União.","Juiz define o estabelecimento em 24 horas.","Transferência do agressor que ameace a vítima.","Transferência excepcional em risco iminente."]'::jsonb, '["Juiz define o estabelecimento em 24 horas.","ATUALIZAÇÃO: §§3º a 5º incluídos por leis posteriores."]'::jsonb, 'Em uma rebelião, a administração transfere presos e comunica o juiz.', '["Assertiva que fixa em 48 horas o prazo do juiz para definir o estabelecimento erra: são 24 horas."]'::jsonb, '[]'::jsonb, '["Art. 87"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-86'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A penitenciária destina-se ao condenado à pena de reclusão, em regime fechado. A União, os Estados, o Distrito Federal e os Territórios poderão construir penitenciárias destinadas exclusivamente aos presos provisórios e condenados em regime fechado sujeitos ao regime disciplinar diferenciado.', '["Penitenciária: reclusão em regime fechado.","Penitenciárias exclusivas para presos no RDD."]'::jsonb, '["Penitenciária = regime FECHADO."]'::jsonb, 'O condenado à reclusão em regime fechado cumpre pena na penitenciária.', '["Assertiva que destina a penitenciária ao regime semiaberto erra."]'::jsonb, '[]'::jsonb, '["Art. 91"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-87'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O condenado será alojado em cela individual que conterá dormitório, aparelho sanitário e lavatório. São requisitos básicos da unidade celular a salubridade do ambiente, pela concorrência dos fatores de aeração, insolação e condicionamento térmico adequado, e a área mínima de 6,00 m².', '["Cela individual.","Salubridade.","Área mínima de 6,00 m²."]'::jsonb, '["Área mínima de 6 metros quadrados."]'::jsonb, 'A cela individual deve ter pelo menos 6 m².', '["Assertiva que fixa em 3 m² a área mínima da cela erra: são 6,00 m²."]'::jsonb, '[]'::jsonb, '["Art. 92"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-88'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Além dos requisitos do art. 88, a penitenciária de mulheres será dotada de seção para gestante e parturiente e de creche para abrigar crianças maiores de 6 meses e menores de 7 anos, com a finalidade de assistir a criança desamparada cuja responsável estiver presa. A seção e a creche exigem atendimento por pessoal qualificado, em unidades autônomas, e horário de funcionamento que garanta a melhor assistência à criança e à sua responsável.', '["Seção para gestante e parturiente.","Creche para crianças maiores de 6 meses e menores de 7 anos.","Pessoal qualificado e unidades autônomas."]'::jsonb, '["Creche: maiores de 6 meses e menores de 7 anos."]'::jsonb, 'A penitenciária feminina mantém creche para filhos de presas com mais de 6 meses.', '["Assertiva que fixa a creche para crianças de até 12 anos erra: são menores de 7 anos."]'::jsonb, '[]'::jsonb, '["Art. 83"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-89'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A penitenciária de homens será construída em local afastado do centro urbano, a distância que não restrinja a visitação.', '["Local afastado do centro urbano.","Distância que não restrinja a visitação."]'::jsonb, '["Afastada, mas que permita visitas."]'::jsonb, 'A penitenciária fica fora da cidade, em local de acesso viável aos visitantes.', '["Assertiva que manda construir a penitenciária no centro urbano erra."]'::jsonb, '[]'::jsonb, '["Art. 87"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-90'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A Colônia Agrícola, Industrial ou Similar destina-se ao cumprimento da pena em regime semiaberto.', '["Colônia agrícola ou industrial: regime semiaberto."]'::jsonb, '["Colônia = SEMIABERTO."]'::jsonb, 'O condenado em regime semiaberto cumpre pena em colônia agrícola.', '["Assertiva que destina a colônia agrícola ao regime fechado erra."]'::jsonb, '[]'::jsonb, '["Art. 92"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-91'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O condenado poderá ser alojado em compartimento coletivo, observados os requisitos de salubridade do art. 88. São também requisitos básicos das dependências coletivas a seleção adequada dos presos e o limite de capacidade máxima que atenda os objetivos de individualização da pena.', '["Alojamento coletivo permitido.","Seleção adequada dos presos.","Limite de capacidade que atenda à individualização."]'::jsonb, '["Alojamento coletivo é típico do semiaberto."]'::jsonb, 'Na colônia, os presos ficam em alojamento coletivo selecionado.', '["Assertiva que dispensa a seleção dos presos nas dependências coletivas erra."]'::jsonb, '[]'::jsonb, '["Art. 88"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-92'
