on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Quando houver condenação por mais de um crime, no mesmo processo ou em processos distintos, a determinação do regime de cumprimento será feita pelo resultado da soma ou unificação das penas, observada, quando for o caso, a detração ou remição. Sobrevindo condenação no curso da execução, somar-se-á a pena ao restante da que está sendo cumprida, para determinação do regime.', '["Regime pela soma ou unificação das penas.","Condenação superveniente soma-se ao restante."]'::jsonb, '["Regime definido pelo RESULTADO da soma."]'::jsonb, 'Duas condenações são somadas para definir o regime.', '["Assertiva que fixa o regime por cada pena isoladamente erra: pela soma ou unificação."]'::jsonb, '[]'::jsonb, '["Art. 112"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-111'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A pena privativa de liberdade será executada de forma progressiva, com a transferência para regime menos rigoroso, quando o preso tiver cumprido ao menos 1/6 da pena no regime anterior e seu mérito indicar a progressão, com as seguintes exceções: primário em crime com violência ou grave ameaça, 25%; reincidente em crime com violência ou grave ameaça, 30%; reincidente em crime diverso, 20%; hediondo ou equiparado primário, 70%; 75% para hediondo com resultado morte (primário, vedado o livramento condicional), comando de organização criminosa ultraviolenta, constituição de milícia privada e feminicídio (primário); reincidente em hediondo ou equiparado, 80%; e reincidente em hediondo com resultado morte, 85%, vedado o livramento condicional. Exige-se boa conduta carcerária e, na decisão, manifestação do Ministério Público e do defensor. A mulher gestante ou mãe ou responsável por crianças ou pessoas com deficiência tem progressão especial, com 1/8 da pena, cumulando requisitos. O tráfico privilegiado não é hediondo. A falta grave interrompe o prazo da progressão, e o bom comportamento é readquirido após 1 ano.', '["Regra geral: 1/6 da pena.","Percentuais: 25%, 30%, 20%, 70%, 75%, 80% e 85%.","Boa conduta carcerária.","Progressão especial de 1/8 para mulheres gestantes e mães ou responsáveis.","Tráfico privilegiado não é hediondo.","Falta grave interrompe o prazo; bom comportamento é readquirido após 1 ano."]'::jsonb, '["ATUALIZAÇÃO: redação dada pelo Pacote Anticrime, com alterações posteriores (inclusive feminicídio e milícia privada).","A falta grave INTERROMPE o prazo da progressão.","Hediondo primário: 70%; reincidente em hediondo: 80%."]'::jsonb, 'O primário condenado por crime hediondo precisa cumprir 70% da pena para progredir.', '["Assertiva que fixa em 40% a fração do primário em crime hediondo erra: é 70% na redação vigente."]'::jsonb, '[{"termo":"Progressão de regime","significado":"Passagem para regime menos rigoroso após cumprir fração da pena."}]'::jsonb, '["Lei dos Crimes Hediondos"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-112'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

