select u.id, u.content_sha256, 'O Juiz poderá modificar as condições estabelecidas, de ofício, a requerimento do Ministério Público, da autoridade administrativa ou do condenado, desde que as circunstâncias assim o recomendem.', '["Modificação das condições de ofício ou a requerimento."]'::jsonb, '["Legitimados: MP, autoridade administrativa e condenado."]'::jsonb, 'O juiz ajusta o horário de recolhimento a pedido do condenado.', '["Assertiva que impede o juiz de modificar as condições de ofício erra."]'::jsonb, '[]'::jsonb, '["Art. 115"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-116'
