insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Somente se admitirá o recolhimento do beneficiário de regime aberto em residência particular quando se tratar de condenado maior de 70 anos; condenado acometido de doença grave; condenada com filho menor ou deficiente físico ou mental; ou condenada gestante.', '["Maior de 70 anos.","Doença grave.","Condenada com filho menor ou com deficiência.","Condenada gestante."]'::jsonb, '["Prisão domiciliar da LEP: maior de 70 anos, doença grave, mãe de menor ou deficiente, gestante."]'::jsonb, 'O condenado de 72 anos no regime aberto pode cumprir em residência particular.', '["Assertiva que fixa em 60 anos a idade para a prisão domiciliar do art. 117 erra: são 70."]'::jsonb, '[]'::jsonb, '["Art. 114"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-117'
