insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A execução da pena privativa de liberdade ficará sujeita à forma regressiva, com a transferência para qualquer dos regimes mais rigorosos, quando o condenado praticar fato definido como crime doloso ou falta grave; ou sofrer condenação, por crime anterior, cuja pena, somada ao restante da pena em execução, torne incabível o regime. O condenado será transferido do regime aberto se, além disso, frustrar os fins da execução ou não pagar, podendo, a multa cumulativamente imposta. Nas hipóteses de crime doloso ou falta grave e de frustração, deverá ser ouvido previamente o condenado.', '["Regressão por crime doloso ou falta grave.","Regressão por condenação que torne incabível o regime.","Do aberto: também por frustrar os fins da execução ou não pagar a multa podendo.","Oitiva prévia do condenado."]'::jsonb, '["Oitiva PRÉVIA do condenado.","Regressão pode ir a QUALQUER regime mais rigoroso."]'::jsonb, 'O condenado que comete falta grave é regredido, depois de ouvido.', '["Assertiva que dispensa a oitiva prévia do condenado na regressão erra."]'::jsonb, '[]'::jsonb, '["Art. 112"]'::jsonb, 'under_review', 'claude'
