insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O condenado por crimes contra a dignidade sexual somente ingressará em regime mais benéfico de cumprimento de pena ou perceberá benefício penal que autorize a saída do estabelecimento se os resultados do exame criminológico afirmarem a existência de indícios de que não voltará a cometer crimes da mesma natureza.', '["Exame criminológico obrigatório para crimes sexuais.","Indícios de que não reincidirá."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído por lei posterior.","Exame criminológico OBRIGATÓRIO e favorável."]'::jsonb, 'A progressão do condenado por estupro depende de exame criminológico favorável.', '["Assertiva que dispensa o exame criminológico na progressão do condenado por crime sexual erra."]'::jsonb, '[]'::jsonb, '["Art. 112"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-119-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os condenados que cumprem pena em regime fechado ou semiaberto e os presos provisórios poderão obter permissão para sair do estabelecimento, mediante escolta, quando ocorrer falecimento ou doença grave do cônjuge, companheira, ascendente, descendente ou irmão, ou necessidade de tratamento médico. A permissão de saída será concedida pelo diretor do estabelecimento.', '["Permissão de saída com escolta.","Falecimento ou doença grave de familiar; tratamento médico.","Concedida pelo diretor."]'::jsonb, '["Permissão de saída: concedida pelo DIRETOR e com ESCOLTA.","Alcança regime fechado, semiaberto e presos provisórios."]'::jsonb, 'O preso sai com escolta para o velório da mãe, com autorização do diretor.', '["Assertiva que atribui ao juiz a concessão da permissão de saída erra: é do diretor do estabelecimento."]'::jsonb, '[]'::jsonb, '["Art. 122"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-120'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

