insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O tempo remido será computado como pena cumprida, para todos os efeitos.', '["Tempo remido é pena cumprida."]'::jsonb, '["Efeito pleno."]'::jsonb, 'Os dias remidos entram no cálculo da progressão e do livramento.', '["Assertiva que não computa o tempo remido para a progressão erra."]'::jsonb, '[]'::jsonb, '["Art. 126"]'::jsonb, 'under_review', 'claude'
