insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Constitui o crime do art. 299 do Código Penal declarar ou atestar falsamente prestação de serviço para fim de instruir pedido de remição.', '["Falsidade ideológica em atestado para remição."]'::jsonb, '["Crime do art. 299 do Código Penal."]'::jsonb, 'Quem atesta falsamente dias de trabalho para obter remição comete falsidade ideológica.', '["Assertiva que trata o atestado falso para remição como mera falta disciplinar erra: é crime."]'::jsonb, '[]'::jsonb, '["Código Penal, art. 299"]'::jsonb, 'under_review', 'claude'
