insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Reformada a sentença denegatória do livramento, os autos baixarão ao Juízo da execução, para as providências cabíveis.', '["Reforma da denegação: autos voltam ao juízo da execução."]'::jsonb, '["Providências no juízo da execução."]'::jsonb, 'O tribunal reforma a negativa, e o juiz da execução adota as providências.', '["Assertiva que manda o tribunal executar o livramento erra: os autos baixam ao juízo da execução."]'::jsonb, '[]'::jsonb, '["Art. 131"]'::jsonb, 'under_review', 'claude'
