insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'No caso de revogação por outro motivo, não se computará na pena o tempo em que esteve solto o liberado, e tampouco se concederá, em relação à mesma pena, novo livramento.', '["Revogação por outro motivo: tempo solto não conta.","Sem novo livramento para a mesma pena."]'::jsonb, '["Perde o tempo solto e não tem novo livramento."]'::jsonb, 'Quem descumpre as condições perde o período solto e o direito a novo livramento.', '["Assertiva que permite novo livramento para a mesma pena após a revogação por descumprimento erra."]'::jsonb, '[]'::jsonb, '["Art. 141"]'::jsonb, 'under_review', 'claude'
