insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Juiz, de ofício, a requerimento do Ministério Público, da Defensoria Pública ou mediante representação do Conselho Penitenciário, e ouvido o liberado, poderá modificar as condições especificadas na sentença, devendo o ato decisório ser lido ao liberado por uma das autoridades indicadas no art. 137, observados os procedimentos ali previstos.', '["Modificação das condições, ouvido o liberado.","Leitura da decisão ao liberado."]'::jsonb, '["ATUALIZAÇÃO: a Defensoria Pública foi incluída entre os legitimados."]'::jsonb, 'A Defensoria pede a modificação de uma condição do livramento.', '["Assertiva que exclui a Defensoria Pública entre os legitimados a pedir a modificação erra."]'::jsonb, '[]'::jsonb, '["Art. 137"]'::jsonb, 'under_review', 'claude'
