select u.id, u.content_sha256, 'O Juiz, de ofício, a requerimento do interessado, do Ministério Público ou mediante representação do Conselho Penitenciário, julgará extinta a pena privativa de liberdade, se expirar o prazo do livramento sem revogação.', '["Extinção da pena se o prazo expirar sem revogação."]'::jsonb, '["Extinção da pena ao fim do prazo, sem revogação."]'::jsonb, 'Cumprido o período de prova sem revogação, a pena é declarada extinta.', '["Assertiva que exige novo pedido do condenado para a extinção da pena erra: o juiz pode julgá-la de ofício."]'::jsonb, '[]'::jsonb, '["Art. 143"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-146'
