insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O condenado monitorado será instruído acerca dos cuidados com o equipamento eletrônico e dos deveres de receber visitas do servidor responsável, responder aos seus contatos e cumprir suas orientações; e de abster-se de remover, violar, modificar ou danificar o dispositivo ou permitir que outrem o faça. A violação comprovada dos deveres poderá acarretar, a critério do juiz da execução, ouvidos o Ministério Público e a defesa, a regressão do regime; a revogação da saída temporária; a revogação da prisão domiciliar; ou advertência por escrito.', '["Deveres do monitorado: receber visitas e não violar o equipamento.","Consequências: regressão, revogação da saída temporária, revogação da prisão domiciliar ou advertência."]'::jsonb, '["Violar o equipamento pode levar à regressão."]'::jsonb, 'Quem danifica a tornozeleira pode ter o regime regredido.', '["Assertiva que isenta o monitorado de consequências ao violar o equipamento erra."]'::jsonb, '[]'::jsonb, '["Art. 146-B"]'::jsonb, 'under_review', 'claude'
