insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O condenado por crime contra a mulher por razões da condição do sexo feminino ou por crimes contra a dignidade sexual, ao usufruir de qualquer benefício em que ocorra a sua saída de estabelecimento penal, será fiscalizado por meio de monitoração eletrônica.', '["Monitoração eletrônica obrigatória para esses condenados em qualquer saída."]'::jsonb, '["ATUALIZAÇÃO: artigo ajustado por lei posterior (feminicídio e crimes sexuais).","Monitoração OBRIGATÓRIA."]'::jsonb, 'O condenado por crime sexual em saída temporária usa tornozeleira.', '["Assertiva que torna facultativa a monitoração eletrônica nesses casos erra."]'::jsonb, '[]'::jsonb, '["Art. 146-B"]'::jsonb, 'under_review', 'claude'
