insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Transitada em julgado a sentença que aplicou a pena restritiva de direitos, o Juiz da execução, de ofício ou a requerimento do Ministério Público, promoverá a execução, podendo requisitar a colaboração de entidades públicas ou solicitá-la a particulares.', '["Execução da pena restritiva após o trânsito em julgado.","Colaboração de entidades públicas ou particulares."]'::jsonb, '["Trânsito em julgado é condição."]'::jsonb, 'O juiz promove a execução da prestação de serviços e solicita a colaboração de uma entidade.', '["Assertiva que permite iniciar a execução da pena restritiva antes do trânsito em julgado erra."]'::jsonb, '[]'::jsonb, '["Art. 148"]'::jsonb, 'under_review', 'claude'
