insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Em qualquer fase da execução, poderá o Juiz, motivadamente, alterar a forma de cumprimento das penas de prestação de serviços à comunidade e de limitação de fim de semana, ajustando-as às condições pessoais do condenado e às características do estabelecimento, da entidade ou do programa.', '["Alteração motivada da forma de cumprimento.","Ajuste às condições pessoais."]'::jsonb, '["Alteração motivada, em qualquer fase."]'::jsonb, 'O juiz muda o horário do serviço comunitário por incompatibilidade com o emprego.', '["Assertiva que impede o juiz de alterar a forma de cumprimento da prestação de serviços erra."]'::jsonb, '[]'::jsonb, '["Art. 149"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-148'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Caberá ao Juiz da execução designar a entidade ou programa junto ao qual o condenado trabalhará gratuitamente, de acordo com as suas aptidões; determinar a intimação do condenado, cientificando-o da entidade, dias e horário; e alterar a forma de execução para ajustá-la às modificações da jornada de trabalho. O trabalho terá a duração de 8 horas semanais, aos sábados, domingos e feriados, ou em dias úteis, sem prejudicar a jornada normal. A execução terá início a partir da data do primeiro comparecimento.', '["Designação da entidade pelo juiz.","Intimação do condenado.","Duração de 8 horas semanais.","Início no primeiro comparecimento."]'::jsonb, '["Oito horas SEMANAIS.","Início no PRIMEIRO COMPARECIMENTO."]'::jsonb, 'O condenado presta 8 horas semanais de serviço comunitário aos sábados.', '["Assertiva que fixa em 20 horas semanais a prestação de serviços erra: são 8 horas."]'::jsonb, '[]'::jsonb, '["Art. 150"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-149'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

