select u.id, u.content_sha256, 'A entidade beneficiada com a prestação de serviços encaminhará mensalmente ao Juiz da execução relatório circunstanciado das atividades do condenado, bem como, a qualquer tempo, comunicação sobre ausência ou falta disciplinar.', '["Relatório mensal.","Comunicação imediata de ausência ou falta."]'::jsonb, '["Relatório MENSAL."]'::jsonb, 'A entidade envia todo mês o relatório do condenado ao juiz.', '["Assertiva que fixa relatório semestral da entidade erra: é mensal."]'::jsonb, '[]'::jsonb, '["Art. 149"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-150'
